-- Dibangkitkan oleh scripts/generate_seed.py dari Kertas Kerja Workshop 3. Jangan diedit manual.
begin;
on conflict (id) do update set area = excluded.area, job_function = excluded.job_function, nama = excluded.nama;
on conflict (id) do update set nama = excluded.nama;
on conflict (id) do update set kode = excluded.kode, nama = excluded.nama, level = excluded.level, direktorat = excluded.direktorat, divisi = excluded.divisi;
on conflict (id) do update set strategi = excluded.strategi, inisiatif = excluded.inisiatif, capability = excluded.capability, kompetensi_usulan = excluded.kompetensi_usulan, kekuatan_usulan = excluded.kekuatan_usulan;
select c.id, 1, c.kompetensi_usulan, case
  when exists (select 1 from public.kamus_hard k where lower(k.nama) = lower(c.kompetensi_usulan)) then 'hard'
  when exists (select 1 from public.kamus_leadership k where lower(k.nama) = lower(c.kompetensi_usulan)) then 'leadership'
  else 'usulan' end
from public.capabilities c
where not exists (select 1 from public.learning_needs l where l.capability_id = c.id);
commit;
